window.TESR_EDGE_FILES = {
  "predict.py": "\"\"\"TESR AI Vision Web Trainer - run your exported model.onnx on any edge device.\n\nOne script for PC, Raspberry Pi 5 and NVIDIA Jetson. Needs only:\n    onnxruntime  numpy  opencv        (no TensorFlow, no PyTorch)\n\n    python predict.py                         # camera from config.json (usb / csi)\n    python predict.py --source photo.jpg      # one image\n    python predict.py --source clip.mp4       # a video file\n    python predict.py --camera csi            # ribbon camera (Pi: Picamera2, Jetson: GStreamer)\n    python predict.py --mode single           # detection: only the main object\n    python predict.py --headless              # no window (SSH) - prints results only\n    python predict.py --trt                   # Jetson: the engine build_trt.sh made\n\nThe model knows its own task (config.json):\n  classification -> one class name for the whole frame\n  detection      -> box + CENTER (x, y) in pixels; modes:\n                    multi   every trained object in view, each tracked + smoothed (default)\n                    single  the one main object\n                    precise one object, 25-crop grid scan (slower)\n\nmulti mode lists only the objects it finds (\"0 object(s)\", headless \"[]\" if none);\n--min-conf is its per-object threshold (default multi_conf in config.json) -\nlower finds more, higher is stricter. The similarity gate is not used in multi.\nsingle / precise / classification print \"none\" = nothing you trained is in\nview: confidence below --min-conf (default 0.65) OR the frame does not look\nlike your training photos (prototypes in config.json; --no-proto turns it off).\nWritten for Python 3.6+ so it also runs on Jetson Nano (JetPack 4) - which is\nmore limited than Jetson Orin Nano (performance and support for new software).\n\"\"\"\nimport argparse\nimport json\nimport math\nimport os\nimport platform\nimport sys\nimport time\n\nimport numpy as np\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nGOLD = (76, 168, 201)                 # BGR of TESR gold #c9a84c\nGREY = (120, 120, 120)\n\n\ndef load_config():\n    path = os.path.join(HERE, \"config.json\")\n    if not os.path.exists(path):\n        raise SystemExit(\"config.json not found next to predict.py - unzip the whole export folder\")\n    with open(path, \"r\", encoding=\"utf-8\") as f:\n        return json.load(f)\n\n\ndef is_jetson():\n    return os.path.exists(\"/etc/nv_tegra_release\") or \"tegra\" in platform.release().lower()\n\n\ndef is_raspberry_pi():\n    try:\n        with open(\"/proc/device-tree/model\", \"r\") as f:\n            return \"raspberry pi\" in f.read().lower()\n    except Exception:\n        return False\n\n\n# --------------------------------------------------- TensorRT (Jetson) ---\nENGINES = [\"model_fp16.engine\", \"model_fp32.engine\"]     # written by build_trt.sh\n\n\ndef _cudart():\n    \"\"\"The CUDA runtime that ships with JetPack, loaded with ctypes (no pycuda needed).\"\"\"\n    import ctypes\n    import ctypes.util\n    import glob\n    names = [ctypes.util.find_library(\"cudart\")] + sorted(\n        glob.glob(\"/usr/local/cuda*/lib64/libcudart.so*\") + glob.glob(\"/usr/lib/aarch64-linux-gnu/libcudart.so*\"))\n    for n in names:\n        if not n:\n            continue\n        try:\n            lib = ctypes.CDLL(n)\n        except OSError:\n            continue\n        lib.cudaMalloc.argtypes = [ctypes.POINTER(ctypes.c_void_p), ctypes.c_size_t]\n        lib.cudaMemcpy.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_size_t, ctypes.c_int]\n        return lib\n    raise RuntimeError(\"CUDA runtime (libcudart) not found\")\n\n\nclass TrtSession(object):\n    \"\"\"Runs a .engine from build_trt.sh; same run(None, feed) call as onnxruntime.\"\"\"\n\n    def __init__(self, path):\n        import ctypes\n        import tensorrt as trt\n        self.ct, self.cuda = ctypes, _cudart()\n        with open(path, \"rb\") as f:\n            engine = trt.Runtime(trt.Logger(trt.Logger.WARNING)).deserialize_cuda_engine(f.read())\n        if engine is None:\n            raise RuntimeError(\"TensorRT could not load it (built with another TensorRT version \"\n                               \"or on another board?) - run  bash build_trt.sh  again on this Jetson\")\n        self.engine, self.ctx = engine, engine.create_execution_context()\n        new_api = hasattr(engine, \"num_io_tensors\")             # TensorRT 8.5+ / 10\n        n = engine.num_io_tensors if new_api else engine.num_bindings\n        self.io = []                                             # (name, is_input, host array, device ptr)\n        for i in range(n):\n            if new_api:\n                name = engine.get_tensor_name(i)\n                is_in = engine.get_tensor_mode(name) == trt.TensorIOMode.INPUT\n                shape, dt = engine.get_tensor_shape(name), engine.get_tensor_dtype(name)\n            else:                                                # TensorRT 8.2 (Jetson Nano, JetPack 4)\n                name, is_in = engine.get_binding_name(i), engine.binding_is_input(i)\n                shape, dt = engine.get_binding_shape(i), engine.get_binding_dtype(i)\n            host = np.zeros(tuple(shape), dtype=trt.nptype(dt))\n            ptr = ctypes.c_void_p()\n            if self.cuda.cudaMalloc(ctypes.byref(ptr), host.nbytes) != 0:\n                raise RuntimeError(\"cudaMalloc failed\")\n            if new_api:\n                self.ctx.set_tensor_address(name, ptr.value)\n            self.io.append((name, is_in, host, ptr))\n        self.new_api = new_api\n        self.output_names = [io[0] for io in self.io if not io[1]]\n\n    def run(self, _names, feed):\n        cp = self.cuda.cudaMemcpy\n        for name, is_in, host, ptr in self.io:\n            if is_in:\n                host[...] = feed[name]\n                cp(ptr, host.ctypes.data, host.nbytes, 1)        # host -> GPU\n        if self.new_api:\n            self.ctx.execute_async_v3(0)\n            self.cuda.cudaDeviceSynchronize()\n        else:\n            self.ctx.execute_v2([io[3].value for io in self.io])\n        out = []\n        for name, is_in, host, ptr in self.io:\n            if not is_in:\n                cp(host.ctypes.data, ptr, host.nbytes, 2)        # GPU -> host\n                out.append(host.copy())\n        return out\n\n\ndef open_engine():\n    \"\"\"--trt: the engine build_trt.sh made, or None after printing why not.\"\"\"\n    found = [e for e in ENGINES if os.path.exists(os.path.join(HERE, e))]\n    if not found:\n        print(\"--trt: no %s here - build it on this Jetson first:  bash build_trt.sh\" % \" / \".join(ENGINES))\n        return None\n    try:\n        import tensorrt  # noqa: F401\n    except ImportError:\n        print(\"--trt: found %s, but Python cannot import tensorrt - on the Jetson:\\n\"\n              \"       sudo apt install -y python3-libnvinfer   (the venv must use --system-site-packages,\\n\"\n              \"       install_jetson.sh does this)\" % found[0])\n        return None\n    try:\n        sess = TrtSession(os.path.join(HERE, found[0]))\n    except Exception as e:\n        print(\"--trt: could not use %s: %s\" % (found[0], e))\n        return None\n    sess.provider = \"TensorRT engine %s\" % found[0]\n    return sess\n\n\n# ----------------------------------------------------------------- model ---\nclass Model(object):\n    def __init__(self, cfg, use_gpu=True, trt=False):\n        path = os.path.join(HERE, cfg.get(\"model\", \"model.onnx\"))\n        self.sess = open_engine() if trt else None\n        if self.sess is not None:\n            self.provider, self.outputs = self.sess.provider, self.sess.output_names\n        else:\n            try:\n                import onnxruntime as ort\n            except ImportError:\n                raise SystemExit(\"onnxruntime is not installed. Run the installer in this folder \"\n                                 \"(see README_DEPLOY.md), or:  pip install onnxruntime\")\n            if not os.path.exists(path):\n                raise SystemExit(\"Model file not found: \" + path)\n            avail = ort.get_available_providers()\n            wanted = []\n            if trt and \"TensorrtExecutionProvider\" in avail:\n                # onnxruntime-gpu with TensorRT builds its own engine (trt_cache/, first start is slow)\n                wanted.append((\"TensorrtExecutionProvider\", {\n                    \"trt_fp16_enable\": True, \"trt_engine_cache_enable\": True,\n                    \"trt_engine_cache_path\": os.path.join(HERE, \"trt_cache\")}))\n            if use_gpu and \"CUDAExecutionProvider\" in avail:\n                wanted.append(\"CUDAExecutionProvider\")\n            wanted.append(\"CPUExecutionProvider\")\n            if trt:\n                w = wanted[0] if isinstance(wanted[0], str) else wanted[0][0]\n                print(\"--trt: continuing with onnxruntime \" + w\n                      + (\" (it builds its own engine in trt_cache/ - first start takes minutes)\"\n                         if w == \"TensorrtExecutionProvider\" else \" - no TensorRT\"))\n            self.sess = ort.InferenceSession(path, providers=wanted)\n            self.provider = self.sess.get_providers()[0]\n            self.outputs = [o.name for o in self.sess.get_outputs()]\n        self.size = int(cfg.get(\"input\", 224))\n        self.names = cfg[\"classes\"]\n        self.task = cfg.get(\"task\", \"classification\")\n        self.bg = set(cfg.get(\"background_classes\", []))\n        p = cfg.get(\"prototypes\")\n        self.proto = None\n        if p:\n            C = np.asarray(p[\"centroids\"], dtype=np.float32)\n            C /= np.linalg.norm(C, axis=1, keepdims=True) + 1e-9\n            self.proto = {\"C\": C, \"thr\": float(p[\"threshold\"])}\n\n    def blob(self, bgr):\n        import cv2\n        rgb = cv2.cvtColor(bgr, cv2.COLOR_BGR2RGB)\n        img = cv2.resize(rgb, (self.size, self.size), interpolation=cv2.INTER_LINEAR)\n        return (img.astype(np.float32) / 255.0).transpose(2, 0, 1)[None]\n\n    def run(self, bgr, tta=False):\n        x = self.blob(bgr)\n        out = dict(zip(self.outputs, self.sess.run(None, {\"images\": x})))\n        if tta and (\"box\" in out or \"output0\" in out):\n            # also run the mirrored frame: same objects, independent noise -> steadier boxes\n            xf = np.ascontiguousarray(x[:, :, :, ::-1])\n            of = dict(zip(self.outputs, self.sess.run(None, {\"images\": xf})))\n            if \"box\" in out:\n                bf = of[\"box\"].copy()\n                bf[0, 0] = 1.0 - bf[0, 0]\n                out[\"box\"] = (out[\"box\"] + bf) / 2.0\n            if \"output0\" in of:\n                out[\"output0_flip\"] = of[\"output0\"]\n        return out\n\n    def similarity(self, feat):\n        if self.proto is None:\n            return None\n        f = feat / (np.linalg.norm(feat) + 1e-9)\n        return float(np.max(self.proto[\"C\"] @ f))\n\n\n# ------------------------------------------------------------- deciding ---\ndef decide(model, out, min_conf, proto_th):\n    probs = out[\"probs\"][0]\n    i = int(np.argmax(probs))\n    conf = float(probs[i])\n    sim = model.similarity(out[\"feat\"][0])\n    thr = proto_th if proto_th is not None else (model.proto[\"thr\"] if model.proto else None)\n    name = model.names[i]\n    if conf < min_conf or (sim is not None and thr is not None and sim < thr) or name in model.bg:\n        name = \"none\"\n    return name, conf, probs\n\n\ndef clamp_region(r):\n    cx, cy, w, h = r\n    w = min(max(w, 0.05), 1.0)\n    h = min(max(h, 0.05), 1.0)\n    return (min(max(cx, w / 2), 1 - w / 2), min(max(cy, h / 2), 1 - h / 2), w, h)\n\n\ndef crop(bgr, r):\n    H, W = bgr.shape[:2]\n    cx, cy, w, h = r\n    x1 = max(0, int((cx - w / 2) * W)); x2 = min(W, max(x1 + 2, int((cx + w / 2) * W)))\n    y1 = max(0, int((cy - h / 2) * H)); y2 = min(H, max(y1 + 2, int((cy + h / 2) * H)))\n    return bgr[y1:y2, x1:x2]\n\n\ndef grid_locate(model, bgr, ci):\n    \"\"\"Precise mode: 25 crops (9 coarse + 10 refine + 2 aspect), keep the best.\"\"\"\n    def score(r):\n        return float(model.run(crop(bgr, r))[\"probs\"][0][ci])\n    best, bs = None, -1.0\n    for cy in (0.25, 0.5, 0.75):\n        for cx in (0.25, 0.5, 0.75):\n            r = clamp_region((cx, cy, 0.5, 0.5)); s = score(r)\n            if s > bs:\n                bs, best = s, r\n    for size in (0.32, 0.5):\n        for dx, dy in ((0, 0), (0.12, 0), (-0.12, 0), (0, 0.12), (0, -0.12)):\n            r = clamp_region((best[0] + dx, best[1] + dy, size, size)); s = score(r)\n            if s > bs:\n                bs, best = s, r\n    for r0 in ((best[0], best[1], best[2] * 1.3, best[3] * 0.77),\n               (best[0], best[1], best[2] * 0.77, best[3] * 1.3)):\n        r = clamp_region(r0); s = score(r)\n        if s > bs:\n            bs, best = s, r\n    return list(best)\n\n\ndef iou(a, b):\n    x1, y1 = max(a[0], b[0]), max(a[1], b[1])\n    x2, y2 = min(a[2], b[2]), min(a[3], b[3])\n    inter = max(0.0, x2 - x1) * max(0.0, y2 - y1)\n    if inter <= 0:\n        return 0.0\n    return inter / ((a[2] - a[0]) * (a[3] - a[1]) + (b[2] - b[0]) * (b[3] - b[1]) - inter)\n\n\ndef decode_multi(model, out, min_conf, iou_thr, max_det=20):\n    \"\"\"output0 [1,4+nc,N]: cx,cy,w,h in model pixels + per-class scores.\n    Neighbouring cells that see the same object are MERGED into one score-weighted box\n    (steadier than picking one cell), and the mirrored frame's detections are fused in\n    when available (out[\"output0_flip\"]).\"\"\"\n    s = float(model.size)\n\n    def peaks(o):\n        # keep a cell only where its class score is the local maximum of its 3x3\n        # neighbourhood (one response per object; weak echoes next to it are dropped)\n        n = o.shape[1]\n        g = int(round(math.sqrt(n)))\n        if g * g != n:\n            return o.T\n        sc = o[4:].reshape(-1, g, g)\n        pad = np.pad(sc, ((0, 0), (1, 1), (1, 1)), constant_values=-1.0)\n        nb = np.max([pad[:, 1 + dy:1 + dy + g, 1 + dx:1 + dx + g]\n                     for dy in (-1, 0, 1) for dx in (-1, 0, 1)], axis=0)\n        sc = np.where(sc >= nb, sc, 0.0)\n        o = o.copy()\n        o[4:] = sc.reshape(-1, n)\n        return o.T\n\n    preds = [peaks(out[\"output0\"][0])]\n    if \"output0_flip\" in out:\n        pf = peaks(out[\"output0_flip\"][0]).copy()\n        pf[:, 0] = s - pf[:, 0]\n        preds.append(pf)\n    pred = np.concatenate(preds, 0)                     # [N, 4+nc]\n    scores = pred[:, 4:]\n    cls = np.argmax(scores, axis=1)\n    conf = scores[np.arange(len(cls)), cls]\n    bg = set(i for i, n in enumerate(model.names) if n in model.bg)\n    keep = [k for k in np.where(conf >= min_conf)[0] if int(cls[k]) not in bg]\n    keep.sort(key=lambda k: -conf[k])\n    groups = []\n    for k in keep:\n        cx, cy, w, h = pred[k, :4] / s\n        box = [cx - w / 2, cy - h / 2, cx + w / 2, cy + h / 2]\n        c = int(cls[k])\n        for g in groups:\n            o = iou(g[\"xyxy\"], box)\n            inside = g[\"xyxy\"][0] <= cx <= g[\"xyxy\"][2] and g[\"xyxy\"][1] <= cy <= g[\"xyxy\"][3]\n            # center inside a stronger box = same object (any class); else same-class overlap\n            if inside or (g[\"cls\"] == c and o > iou_thr) or o > 0.5:\n                g[\"m\"].append((float(conf[k]), [cx, cy, w, h]))\n                break\n        else:\n            if len(groups) < max_det:\n                groups.append({\"cls\": c, \"conf\": float(conf[k]), \"xyxy\": box, \"m\": [(float(conf[k]), [cx, cy, w, h])]})\n    dets = []\n    for g in groups:\n        wts = np.array([m[0] for m in g[\"m\"]]); bx = np.array([m[1] for m in g[\"m\"]])\n        b = (bx * wts[:, None]).sum(0) / wts.sum()\n        dets.append({\"cls\": g[\"cls\"], \"name\": model.names[g[\"cls\"]], \"conf\": g[\"conf\"],\n                     \"xyxy\": [b[0] - b[2] / 2, b[1] - b[3] / 2, b[0] + b[2] / 2, b[1] + b[3] / 2],\n                     \"box\": [float(v) for v in b]})\n    return dets\n\n\nSTEADY_PRESETS = {\n    # One Euro filter: strong smoothing while the object is still, almost no lag when it\n    # moves. min_cutoff = smoothing at rest (lower = steadier), beta = how fast it follows\n    # motion, deadband = ignore changes smaller than this (fraction of the frame).\n    \"high\":   {\"min_cutoff\": 0.05, \"beta\": 4.0, \"d_cutoff\": 1.0, \"deadband\": 0.006},\n    \"normal\": {\"min_cutoff\": 0.10, \"beta\": 6.0, \"d_cutoff\": 1.0, \"deadband\": 0.004},\n    \"low\":    {\"min_cutoff\": 0.50, \"beta\": 10.0, \"d_cutoff\": 1.0, \"deadband\": 0.002},\n}\n\n\nclass Stabilizer(object):\n    \"\"\"Steadies the single-object result between frames (tuned on real footage).\n    - box: One Euro filter + small deadband, time-based so it behaves the same at any FPS\n    - class: switches only after it is seen on 2 frames in a row; confidence is smoothed\n    - \"none\": the last box is held for a few frames (a hand passing by, motion blur)\"\"\"\n\n    def __init__(self, preset=\"normal\", hold=6):\n        self.off = preset == \"off\"\n        p = STEADY_PRESETS.get(preset, STEADY_PRESETS[\"normal\"])\n        self.mc, self.beta, self.dc, self.db = p[\"min_cutoff\"], p[\"beta\"], p[\"d_cutoff\"], p[\"deadband\"]\n        self.hold = hold\n        self.reset()\n        self.cand, self.cand_n, self.miss = None, 0, 0\n        self.name, self.conf = None, 0.0\n\n    def reset(self):\n        self.x = self.dx = self.shown = None\n        self.t = None\n\n    @staticmethod\n    def _alpha(cutoff, dt):\n        r = 2 * math.pi * cutoff * dt\n        return r / (r + 1)\n\n    def _filter(self, box, now):\n        z = np.asarray(box, dtype=np.float64)\n        if self.off:\n            return list(z)\n        if self.x is None:\n            self.x, self.dx, self.shown, self.t = z.copy(), np.zeros(4), z.copy(), now\n            return list(z)\n        dt = min(max(now - self.t, 1e-3), 0.5)\n        self.t = now\n        self.dx = self.dx + self._alpha(self.dc, dt) * ((z - self.x) / dt - self.dx)\n        cut = self.mc + self.beta * np.abs(self.dx)\n        a = 2 * math.pi * cut * dt\n        self.x = self.x + (a / (a + 1)) * (z - self.x)\n        moved = np.abs(self.x - self.shown) > np.array([self.db, self.db, self.db * 1.5, self.db * 1.5])\n        self.shown[moved] = self.x[moved]\n        return list(self.shown)\n\n    def update(self, name, conf, box, now=None):\n        now = time.time() if now is None else now\n        if name == \"none\" or box is None:\n            self.miss += 1\n            if self.shown is not None and self.miss <= self.hold:\n                return self.name, self.conf, list(self.shown)\n            self.reset()\n            self.name, self.cand, self.cand_n = None, None, 0\n            return \"none\", conf, None\n        self.miss = 0\n        if self.name is not None and name != self.name:\n            self.cand_n = self.cand_n + 1 if name == self.cand else 1\n            self.cand = name\n            if self.cand_n < 2:                      # not confirmed yet: keep the current answer\n                return self.name, self.conf, list(self.shown)\n            self.reset()                             # confirmed switch: start fresh\n        self.cand, self.cand_n = None, 0\n        self.conf = conf if (self.name != name or self.off) else self.conf + 0.3 * (conf - self.conf)\n        self.name = name\n        return self.name, self.conf, self._filter(box, now)\n\n\nclass MultiSteadier(object):\n    \"\"\"Many objects at once: each detection is matched to a track (by overlap / distance),\n    and every track has its own Stabilizer - same smoothing, hold and class\n    hysteresis as single-object mode. Tracks keep an id (#1, #2 ...) while visible.\"\"\"\n\n    def __init__(self, preset=\"high\", hold=6, confirm=3):\n        self.preset, self.hold, self.confirm = preset, hold, confirm\n        self.tracks = []            # dicts: id, st (Stabilizer), box (last raw xywh), hits\n\n    def _new_id(self):\n        used = set(t[\"id\"] for t in self.tracks)\n        i = 1\n        while i in used:\n            i += 1\n        return i                    # lowest free number: objects stay 1, 2, 3 ...\n\n    @staticmethod\n    def _cost(a, b):\n        ax = [a[0] - a[2] / 2, a[1] - a[3] / 2, a[0] + a[2] / 2, a[1] + a[3] / 2]\n        bx = [b[0] - b[2] / 2, b[1] - b[3] / 2, b[0] + b[2] / 2, b[1] + b[3] / 2]\n        o = iou(ax, bx)\n        d = math.hypot(a[0] - b[0], a[1] - b[1]) / max(1e-6, (a[2] + a[3] + b[2] + b[3]) / 4)\n        return o, d\n\n    def update(self, dets, now=None, start_conf=0.0):\n        \"\"\"dets may include weak detections: they can only CONTINUE an existing track;\n        starting a new object needs conf >= start_conf (hysteresis -> stable ids).\"\"\"\n        now = time.time() if now is None else now\n        pairs = []\n        for ti, t in enumerate(self.tracks):\n            for di, d in enumerate(dets):\n                o, dist = self._cost(t[\"box\"], d[\"box\"])\n                if o > 0.15 or dist < 0.6:\n                    pairs.append((-(o - 0.2 * dist), ti, di))\n        pairs.sort()\n        used_t, used_d, out = set(), set(), []\n        for _, ti, di in pairs:\n            if ti in used_t or di in used_d:\n                continue\n            used_d.add(di)\n            t, d = self.tracks[ti], dets[di]\n            if d[\"conf\"] < start_conf:\n                continue        # weak: keeps the object from being re-created, but never moves/shows a box\n            used_t.add(ti)\n            t[\"box\"] = d[\"box\"]\n            t[\"hits\"] += 1\n            name, conf, box = t[\"st\"].update(d[\"name\"], d[\"conf\"], d[\"box\"], now)\n            if box is not None and t[\"hits\"] >= self.confirm:\n                out.append({\"id\": t[\"id\"], \"name\": name, \"conf\": conf, \"box\": box})\n        alive = []\n        for ti, t in enumerate(self.tracks):\n            if ti not in used_t:\n                if t[\"hits\"] < self.confirm:\n                    continue                                              # never confirmed: drop\n                name, conf, box = t[\"st\"].update(\"none\", 0.0, None, now)   # hold for a few frames\n                if box is None:\n                    continue\n                out.append({\"id\": t[\"id\"], \"name\": name, \"conf\": conf, \"box\": box})\n            alive.append(t)\n        self.tracks = alive\n        for di, d in enumerate(dets):\n            if di in used_d or d[\"conf\"] < start_conf:\n                continue\n            st = Stabilizer(self.preset, self.hold)\n            name, conf, box = st.update(d[\"name\"], d[\"conf\"], d[\"box\"], now)\n            t = {\"id\": self._new_id(), \"st\": st, \"box\": d[\"box\"], \"hits\": 1}\n            self.tracks.append(t)\n            if self.confirm <= 1:\n                out.append({\"id\": t[\"id\"], \"name\": name, \"conf\": conf, \"box\": box})\n        out.sort(key=lambda r: r[\"id\"])\n        return out\n\n\n# --------------------------------------------------------------- drawing ---\ndef draw_box(bgr, name, conf, box, idx=None):\n    \"\"\"Box + center cross + one label:  #1 Orange 100% (128, 262)\n    The label sits just above the box (inside it when there is no room above) and is\n    always kept fully inside the image, on a dark strip so it stays readable.\"\"\"\n    import cv2\n    H, W = bgr.shape[:2]\n    cx, cy, bw, bh = box\n    px, py = int(cx * W), int(cy * H)\n    x1, y1 = int((cx - bw / 2) * W), int((cy - bh / 2) * H)\n    x2, y2 = int((cx + bw / 2) * W), int((cy + bh / 2) * H)\n    cv2.rectangle(bgr, (x1, y1), (x2, y2), GOLD, 2)\n    cv2.drawMarker(bgr, (px, py), GOLD, cv2.MARKER_CROSS, 18, 2)\n    label = \"%s %d%% (%d, %d)\" % (name, round(conf * 100), px, py)\n    if idx is not None:\n        label = \"#%d %s\" % (idx, label)\n    font, scale, th = cv2.FONT_HERSHEY_SIMPLEX, 0.45, 1\n    (tw, tht), base = cv2.getTextSize(label, font, scale, th)\n    pad = 4\n    lw, lh = tw + 2 * pad, tht + base + 2 * pad\n    lx = min(max(0, x1), max(0, W - lw))                      # stay inside the image\n    ly = y1 - lh if y1 - lh >= 0 else max(0, min(y1, H - lh))  # above the box, else inside it\n    cv2.rectangle(bgr, (lx, ly), (lx + lw, ly + lh), (12, 17, 20), -1)\n    cv2.putText(bgr, label, (lx + pad, ly + pad + tht), font, scale, GOLD, th, cv2.LINE_AA)\n    return px, py\n\n\ndef put(bgr, text, y, color=GOLD, scale=0.7):\n    import cv2\n    cv2.putText(bgr, text, (10, y), cv2.FONT_HERSHEY_SIMPLEX, scale, color, 2)\n\n\n# ---------------------------------------------------------------- camera ---\nclass Camera(object):\n    \"\"\"USB webcam, Pi CSI (Picamera2) or Jetson CSI (GStreamer) behind one read().\"\"\"\n\n    def __init__(self, kind, index, width, height):\n        import cv2\n        self.picam = None\n        self.cap = None\n        if kind == \"csi\" and not is_jetson():\n            try:\n                from picamera2 import Picamera2\n            except ImportError:\n                raise SystemExit(\n                    \"CSI camera needs Picamera2:  sudo apt install -y python3-picamera2\\n\"\n                    \"and a venv made with --system-site-packages (install_pi.sh does this).\")\n            self.picam = Picamera2(index)\n            self.picam.configure(self.picam.create_preview_configuration(\n                main={\"format\": \"RGB888\", \"size\": (width, height)}))   # RGB888 = BGR order for OpenCV\n            self.picam.start()\n            time.sleep(0.5)\n            return\n        if kind == \"csi\":                               # Jetson ribbon camera\n            pipe = (\"nvarguscamerasrc sensor-id=%d ! video/x-raw(memory:NVMM),width=1280,height=720,\"\n                    \"framerate=30/1 ! nvvidconv flip-method=0 ! video/x-raw,width=%d,height=%d,\"\n                    \"format=BGRx ! videoconvert ! video/x-raw,format=BGR ! appsink drop=1 max-buffers=1\"\n                    % (index, width, height))\n            self.cap = cv2.VideoCapture(pipe, cv2.CAP_GSTREAMER)\n            if not self.cap.isOpened():\n                raise SystemExit(\n                    \"Could not open the Jetson CSI camera.\\n\"\n                    \"- check the ribbon cable, then:  gst-launch-1.0 nvarguscamerasrc ! fakesink\\n\"\n                    \"- OpenCV must have GStreamer: python3 -c \\\"import cv2;print(cv2.getBuildInformation())\\\" | grep GStreamer\\n\"\n                    \"  (pip's opencv-python has NO GStreamer - use the system python3-opencv)\")\n            return\n        backends = [cv2.CAP_DSHOW, cv2.CAP_MSMF, cv2.CAP_ANY] if os.name == \"nt\" else \\\n                   [getattr(cv2, \"CAP_V4L2\", cv2.CAP_ANY), cv2.CAP_ANY]\n        for be in backends:\n            cap = cv2.VideoCapture(index, be)\n            if cap.isOpened():\n                cap.set(cv2.CAP_PROP_FRAME_WIDTH, width)\n                cap.set(cv2.CAP_PROP_FRAME_HEIGHT, height)\n                ok, _ = cap.read()\n                if ok:\n                    self.cap = cap\n                    return\n            cap.release()\n        raise SystemExit(\n            \"Could not open USB camera %d.\\n\"\n            \"- try --source 1 (or 2); list cameras on Linux:  v4l2-ctl --list-devices\\n\"\n            \"- close other apps using it (browser Live Test tab, Zoom, Teams)\\n\"\n            \"- ribbon camera? use --camera csi\" % index)\n\n    def read(self):\n        if self.picam is not None:\n            return True, self.picam.capture_array()\n        return self.cap.read()\n\n    def release(self):\n        if self.picam is not None:\n            self.picam.stop()\n        if self.cap is not None:\n            self.cap.release()\n\n\n# ------------------------------------------------------------------ main ---\ndef main():\n    cfg = load_config()\n    ap = argparse.ArgumentParser(description=\"Run a TESR web-trained ONNX model\")\n    ap.add_argument(\"--source\", default=None, help=\"camera index (0,1..) or image/video path\")\n    ap.add_argument(\"--camera\", choices=[\"usb\", \"csi\"], default=None,\n                    help=\"camera type (default from config.json: %s)\" % cfg.get(\"camera\", \"usb\"))\n    ap.add_argument(\"--mode\", choices=[\"auto\", \"classify\", \"single\", \"precise\", \"multi\"], default=\"auto\",\n                    help=\"auto = config.json (%s)\" % cfg.get(\"detect_mode\", \"single\"))\n    ap.add_argument(\"--min-conf\", type=float, default=None,\n                    help=\"confidence gate (default %.2f)\" % cfg.get(\"min_conf\", 0.65))\n    ap.add_argument(\"--iou\", type=float, default=0.45, help=\"multi mode: NMS overlap\")\n    ap.add_argument(\"--proto-th\", type=float, default=None, help=\"override the similarity gate\")\n    ap.add_argument(\"--no-proto\", action=\"store_true\", help=\"disable the similarity gate\")\n    ap.add_argument(\"--width\", type=int, default=640)\n    ap.add_argument(\"--height\", type=int, default=480)\n    ap.add_argument(\"--headless\", action=\"store_true\", help=\"no window; print results only\")\n    ap.add_argument(\"--record\", default=None,\n                    help=\"also save the RAW camera frames (no boxes drawn) to this video, e.g. clip.mp4\")\n    ap.add_argument(\"--cpu\", action=\"store_true\", help=\"force CPU even if a GPU provider exists\")\n    ap.add_argument(\"--trt\", action=\"store_true\",\n                    help=\"Jetson: run model_fp16.engine (or model_fp32.engine) built by build_trt.sh; \"\n                         \"without it, says why and runs on onnxruntime\")\n    ap.add_argument(\"--steady\", choices=[\"auto\", \"high\", \"normal\", \"low\", \"off\"], default=\"auto\",\n                    help=\"box steadiness: high = steadiest, low = follows fastest, off = raw \"\n                         \"(auto = config.json, default high)\")\n    ap.add_argument(\"--hold\", type=int, default=None, help=\"frames to keep the last box when the object is briefly lost (default 6)\")\n    ap.add_argument(\"--tta\", choices=[\"auto\", \"on\", \"off\"], default=\"auto\",\n                    help=\"also run the mirrored frame and average the box (steadier, 2x compute). \"\n                         \"auto = on, except on Raspberry Pi\")\n    args = ap.parse_args()\n\n    import cv2\n\n    model = Model(cfg, use_gpu=not args.cpu, trt=args.trt)\n    if args.no_proto:\n        model.proto = None\n    min_conf = args.min_conf if args.min_conf is not None else float(cfg.get(\"min_conf\", 0.65))\n    mode = args.mode if args.mode != \"auto\" else cfg.get(\"detect_mode\", \"single\")\n    # multi-object detector threshold (per object); --min-conf overrides it\n    multi_conf = args.min_conf if args.min_conf is not None else float(cfg.get(\"multi_conf\", 0.4))\n    if model.task != \"detection\":\n        mode = \"classify\"\n    if mode == \"multi\" and \"output0\" not in model.outputs:\n        raise SystemExit(\"--mode multi needs a detection export (output0 missing)\")\n\n    tta = args.tta == \"on\" or (args.tta == \"auto\" and not is_raspberry_pi() and cfg.get(\"target\") != \"pi5\")\n    tta = tta and mode in (\"single\", \"precise\", \"multi\")\n    steady = args.steady if args.steady != \"auto\" else (cfg.get(\"steady\") or {}).get(\"preset\", \"high\")\n    hold = args.hold if args.hold is not None else int((cfg.get(\"steady\") or {}).get(\"hold\", 6))\n    stab = Stabilizer(steady, hold=max(0, hold))\n    mstab = MultiSteadier(steady, hold=max(0, hold) + 4)\n    print(\"TESR model v%s | task: %s | mode: %s | runtime: %s\"\n          % (cfg.get(\"trainer_version\", \"?\"), model.task, mode, model.provider))\n    if mode in (\"single\", \"precise\", \"multi\"):\n        print(\"steady: %s | hold %d frames | mirror-average %s\" % (steady, stab.hold, \"on\" if tta else \"off\"))\n    print(\"classes: \" + \", \".join(model.names))\n    if model.proto is not None and mode != \"multi\":\n        print('\"none\" gates: confidence < %.2f OR similarity < %.2f'\n              % (min_conf, args.proto_th if args.proto_th is not None else model.proto[\"thr\"]))\n\n    def run_frame(bgr):\n        out = model.run(bgr, tta=tta)\n        if mode == \"multi\":\n            # weak detections (>= half the threshold) may only keep an existing object alive\n            dets = decode_multi(model, out, multi_conf * 0.5, args.iou)\n            H, W = bgr.shape[:2]\n            res = []\n            for d in mstab.update(dets, start_conf=multi_conf):\n                px, py = draw_box(bgr, d[\"name\"], d[\"conf\"], d[\"box\"], d[\"id\"])\n                res.append((d[\"id\"], d[\"name\"], round(d[\"conf\"], 3), (px, py)))\n            put(bgr, \"%d object(s)\" % len(res), H - 14, GOLD, 0.6)\n            return res\n        name, conf, _ = decide(model, out, min_conf, args.proto_th)\n        if mode == \"classify\":\n            put(bgr, \"%s %d%%\" % (name, round(conf * 100)) if name != \"none\" else \"none\", 34,\n                GREY if name == \"none\" else GOLD, 1.0)\n            return [(name, round(conf, 3), None)]\n        box = None\n        if name != \"none\":\n            if mode == \"precise\":\n                box = grid_locate(model, bgr, model.names.index(name))\n            else:\n                box = [float(v) for v in out[\"box\"][0]]\n        name, conf, box = stab.update(name, conf, box)\n        if box is None:\n            put(bgr, \"none\", 34, GREY, 1.0)\n            return [(\"none\", round(conf, 3), None)]\n        px, py = draw_box(bgr, name, conf, box)\n        return [(name, round(conf, 3), (px, py))]\n\n    def show(bgr, title):\n        if args.headless:\n            return False\n        cv2.imshow(title, bgr)\n        return (cv2.waitKey(1) & 0xFF) == ord(\"q\")\n\n    src = args.source if args.source is not None else str(cfg.get(\"camera_index\", 0))\n    if not src.isdigit():\n        if not os.path.exists(src):\n            raise SystemExit(\"File not found: \" + src)\n        if src.lower().endswith((\".jpg\", \".jpeg\", \".png\", \".bmp\", \".webp\")):\n            bgr = cv2.imread(src)\n            if bgr is None:\n                raise SystemExit(\"Could not read image: \" + src)\n            mstab.confirm = 1                 # a single photo: show detections straight away\n            print(run_frame(bgr))\n            if not args.headless:\n                cv2.imshow(\"TESR model (press any key)\", bgr)\n                cv2.waitKey(0)\n                cv2.destroyAllWindows()\n            return\n        cam = cv2.VideoCapture(src)\n        reader = cam.read\n        release = cam.release\n    else:\n        kind = args.camera or cfg.get(\"camera\", \"usb\")\n        cam = Camera(kind, int(src), args.width, args.height)\n        reader = cam.read\n        release = cam.release\n\n    fps, t_last, n = 0.0, time.time(), 0\n    writer = None\n    try:\n        while True:\n            ok, bgr = reader()\n            if not ok or bgr is None:\n                break\n            if bgr.ndim == 3 and bgr.shape[2] == 4:\n                bgr = cv2.cvtColor(bgr, cv2.COLOR_BGRA2BGR)\n            if args.record:\n                if writer is None:\n                    writer = cv2.VideoWriter(args.record, cv2.VideoWriter_fourcc(*\"mp4v\"), 30,\n                                             (bgr.shape[1], bgr.shape[0]))\n                    print(\"recording raw frames to \" + args.record)\n                writer.write(bgr)                   # before anything is drawn\n            res = run_frame(bgr)\n            n += 1\n            now = time.time()\n            if now - t_last >= 1.0:\n                fps = n / (now - t_last)\n                n, t_last = 0, now\n                if args.headless:\n                    print(\"%.1f FPS  %s\" % (fps, res))\n            put(bgr, \"%.1f FPS\" % fps, bgr.shape[0] - 40, GOLD, 0.55)\n            if show(bgr, \"TESR model - press q to quit\"):\n                break\n    except KeyboardInterrupt:\n        pass\n    finally:\n        if writer is not None:\n            writer.release()\n        release()                          # always free the camera\n        if not args.headless:\n            cv2.destroyAllWindows()\n\n\nif __name__ == \"__main__\":\n    main()\n",
  "export.py": "\"\"\"TESR web model - package it for a device (run this ON YOUR COMPUTER).\n\n    python export.py --target pi                  # Raspberry Pi 5\n    python export.py --target jetson              # Jetson Orin Nano / NX / AGX\n    python export.py --target jetson_nano         # old Jetson Nano (JetPack 4, experimental; more limited than Orin Nano)\n\nThe export picks the BOARD. Which camera to open is decided on the device,\nwhen you run predict.py there:  python predict.py --camera usb --source 0\n(optional --camera usb|csi here only sets the default written into config.json)\n\nCreates  exports/tesr-model-<target>/  and  exports/tesr-model-<target>.zip\ncontaining only what the device needs (model + predict.py + its installer).\nCopy that folder/zip to the board, then:  bash install_pi.sh  (or install_jetson.sh)\nand  python predict.py\n\nSame model.onnx on every device - nothing is retrained or converted here.\nJetson speed-up (TensorRT) is built ON the Jetson with  bash build_trt.sh\n\"\"\"\nimport argparse\nimport json\nimport os\nimport shutil\nimport sys\nimport time\nimport zipfile\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nKIT = os.path.join(HERE, \"device_kit\")\n\nTARGETS = {\n    \"pi\":          {\"name\": \"pi5\", \"label\": \"Raspberry Pi 5\",\n                    \"files\": [\"install_pi.sh\"],\n                    \"install\": \"bash install_pi.sh\"},\n    \"jetson\":      {\"name\": \"jetson\", \"label\": \"NVIDIA Jetson Orin Nano / NX / AGX\",\n                    \"files\": [\"install_jetson.sh\", \"build_trt.sh\"],\n                    \"install\": \"bash install_jetson.sh\"},\n    \"jetson_nano\": {\"name\": \"jetson_nano\", \"label\": \"Jetson Nano (JetPack 4, experimental)\",\n                    \"files\": [\"install_jetson.sh\", \"build_trt.sh\"],\n                    \"install\": \"bash install_jetson.sh\"},\n    \"pc\":          {\"name\": \"pc\", \"label\": \"PC (Windows / Linux / macOS)\",\n                    \"files\": [\"install_windows.bat\", \"install_linux.sh\", \"requirements.txt\"],\n                    \"install\": \"install_windows.bat  (Linux: bash install_linux.sh)\"},\n}\nCOMMON = [\"model.onnx\", \"classes.txt\", \"predict.py\", \"README_DEPLOY.md\", \"START_HERE.md\"]\n\n\ndef find(name):\n    for d in (HERE, KIT):\n        p = os.path.join(d, name)\n        if os.path.exists(p):\n            return p\n    return None\n\n\ndef main():\n    ap = argparse.ArgumentParser(description=\"Package this model for a device\")\n    ap.add_argument(\"--target\", required=True, choices=sorted(TARGETS),\n                    help=\"pi | jetson | jetson_nano | pc\")\n    ap.add_argument(\"--camera\", choices=[\"usb\", \"csi\"], default=\"usb\",\n                    help=\"camera on the device (default usb; ribbon camera = csi)\")\n    args = ap.parse_args()\n\n    T = TARGETS[args.target]\n    cfg_path = os.path.join(HERE, \"config.json\")\n    if not os.path.exists(cfg_path):\n        sys.exit(\"config.json not found - run export.py inside the unzipped model folder\")\n    with open(cfg_path, \"r\", encoding=\"utf-8\") as f:\n        cfg = json.load(f)\n\n    missing = [n for n in COMMON + T[\"files\"] if not find(n)]\n    if missing:\n        sys.exit(\"Missing files: %s\\nDownload the model again from the web trainer \"\n                 \"(this folder is from an older version).\" % \", \".join(missing))\n\n    out_dir = os.path.join(HERE, \"exports\", \"tesr-model-\" + T[\"name\"])\n    if os.path.exists(out_dir):\n        shutil.rmtree(out_dir)\n    os.makedirs(out_dir)\n\n    for n in COMMON + T[\"files\"]:\n        shutil.copy2(find(n), os.path.join(out_dir, n))\n    cfg[\"target\"] = \"pi5\" if args.target == \"pi\" else args.target\n    cfg[\"camera\"] = args.camera\n    # keep the long prototype vectors on one line, everything else readable\n    protos = cfg.pop(\"prototypes\", None)\n    text = json.dumps(dict(cfg, prototypes=\"__P__\"), indent=2).replace('\"__P__\"', json.dumps(protos))\n    with open(os.path.join(out_dir, \"config.json\"), \"w\", encoding=\"utf-8\") as f:\n        f.write(text)\n\n    zip_path = out_dir + \".zip\"\n    with zipfile.ZipFile(zip_path, \"w\", zipfile.ZIP_DEFLATED) as z:\n        for n in sorted(os.listdir(out_dir)):\n            info = zipfile.ZipInfo(\"tesr-model-%s/%s\" % (T[\"name\"], n), date_time=time.localtime()[:6])\n            info.compress_type = zipfile.ZIP_DEFLATED\n            mode = 0o755 if n.endswith(\".sh\") else 0o644\n            info.external_attr = (0o100000 | mode) << 16       # keep .sh executable on Linux\n            with open(os.path.join(out_dir, n), \"rb\") as f:\n                z.writestr(info, f.read())\n\n    rel = os.path.relpath(out_dir, HERE)\n    print(\"Done - %s\" % T[\"label\"])\n    print(\"  folder : %s\" % rel)\n    print(\"  zip    : %s.zip\" % rel)\n    print(\"\\nNext, ON THE DEVICE:\")\n    print(\"  1. copy the zip to the board and unzip it\")\n    print(\"  2. %s\" % T[\"install\"])\n    print(\"  3. source venv/bin/activate && python predict.py\")\n    if args.target.startswith(\"jetson\"):\n        print(\"  4. (optional, faster) bash build_trt.sh   -> TensorRT engine built on the Jetson\")\n\n\nif __name__ == \"__main__\":\n    main()\n",
  "requirements.txt": "# TESR web model runtime - PC (Windows / Linux / macOS), Python 3.8+\n# Raspberry Pi and Jetson: use install_pi.sh / install_jetson.sh instead\nonnxruntime\nnumpy\nopencv-python\n",
  "README_DEPLOY.md": "# Deploy your TESR web-trained model\n\nOne flow: **web (train) -> computer (test + export) -> Raspberry Pi / Jetson (run)**.\nNo TensorFlow, no PyTorch - only `onnxruntime` + `numpy` + `opencv`.\n\n| File | What it is |\n|---|---|\n| `model.onnx` | Your model: MobileNetV2 backbone + your trained head(s), input `images [1,3,224,224]` RGB 0..1 |\n| `config.json` | Classes, task, camera type, detection mode, \"none\" gate, box steadiness |\n| `predict.py` | Runs the model on a camera, image or video |\n| `export.py` | Packages this model for a device: `python export.py --target pi\\|jetson\\|jetson_nano` |\n| `install_windows.bat / install_linux.sh` | Installers for the computer |\n| `device_kit/` | Device installers used by `export.py` (`install_pi.sh`, `install_jetson.sh`, `build_trt.sh`) |\n| `project/` | Your photos + labels - the web page's **Load Project** opens this zip |\n\n## 1 - Export for the device (on your computer)\n\n```bash\npython export.py --target pi                  # Raspberry Pi 5\npython export.py --target jetson              # Jetson Orin Nano / NX / AGX\npython export.py --target jetson_nano         # Jetson Nano (JetPack 4, experimental)\n```\nResult: `exports/tesr-model-<target>.zip` - copy it to the board (USB stick, or\n`scp exports/tesr-model-pi5.zip user@device-ip:~/`) and unzip it there.\nThe model file is the same on every device; export only picks the right\ninstaller. Optional: `--camera csi` (default `usb`) writes the default camera\ninto `config.json`; on the device `python predict.py --camera usb|csi` always\noverrides it.\n\n## 2 - Install once\n\n| Device | Command |\n|---|---|\n| Windows PC | double-click `install_windows.bat` |\n| Linux / macOS PC | `bash install_linux.sh` |\n| Raspberry Pi 5 (64-bit Pi OS) | `bash install_pi.sh` |\n| Jetson Orin Nano / NX / AGX | `bash install_jetson.sh` |\n| Jetson Nano (JetPack 4, Python 3.6) | `bash install_jetson.sh` - **experimental**, and more limited than Jetson Orin Nano (performance and support for new software): if pip has no onnxruntime for Python 3.6, install the Jetson build of onnxruntime for JetPack 4.6, or use `bash build_trt.sh` |\n\n> Raspberry Pi: never `sudo pip3 install` - Pi OS blocks it (PEP 668).\n> The installer makes a venv with `--system-site-packages` so the apt\n> OpenCV + Picamera2 are visible inside it.\n\n## 3 - Run\n\n```bash\nsource venv/bin/activate          # Windows: venv\\Scripts\\activate\npython predict.py                 # camera type + mode from config.json\npython predict.py --camera csi    # ribbon camera (Pi: Picamera2 / Jetson: nvarguscamerasrc)\npython predict.py --camera usb --source 1\npython predict.py --source photo.jpg\npython predict.py --headless      # over SSH: prints results + FPS, no window\n```\n\nDetection modes (`--mode`, default from `config.json`):\n\n| Mode | What you get | Notes |\n|---|---|---|\n| `multi` (default) | **every** trained object in view: box + center (x,y) px + track id `#1, #2 ...` | each object is tracked and smoothed on its own |\n| `single` | the one main object: box + center | slightly tighter box when only one object is ever in view |\n| `precise` | one object, 25-crop grid scan | slower |\n\nMulti-object threshold: `--min-conf 0.3` (default from `config.json` `multi_conf`).\nFor the most accurate boxes on crowded scenes, train the YOLO dataset from the\nweb trainer with `yolo-trainer/train.py`.\n\n## 4 - Speed\n\nFPS depends on the device, camera and mode - `predict.py` prints the\n**measured** FPS; always measure on the real device.\n\nJetson GPU (course chapter 6 - ONNX -> TensorRT), on the Jetson itself:\n```bash\nbash build_trt.sh          # builds model_fp32.engine + model_fp16.engine and prints Throughput for each\npython predict.py --trt    # runs model_fp16.engine (model_fp32.engine if there is no FP16 one)\n```\n`--trt` needs JetPack's TensorRT Python module (`sudo apt install -y python3-libnvinfer`).\nThe first line then says `runtime: TensorRT engine model_fp16.engine`. If there is\nno engine, or it cannot be loaded (built on another board / TensorRT version),\n`predict.py` prints why and carries on with onnxruntime - rebuild with `bash build_trt.sh`.\n\n## Troubleshooting\n\n- **No boxes at all (default `multi` mode)** -> multi mode never says \"none\", it shows `0 object(s)` (`--headless` prints `[]`); lower the threshold, e.g. `--min-conf 0.2` (default: `multi_conf` in `config.json`; a higher value such as 0.5 makes it *stricter*). `--no-proto` does nothing in multi mode. Collect more varied photos\n- **Everything is \"none\"** (`--mode single` / `precise`, or a classification model) -> `--min-conf 0.5` (default 0.65), or `--proto-th 0.6`, or `--no-proto`; collect more varied photos\n- **Box steadiness** -> default `--steady high` (smoothest: One Euro filter + mirror-average + hold). Fast robot / conveyor: `--steady normal` or `--steady low` (follows faster). Raw: `--steady off --tta off --hold 0`\n- **An object is missed** -> lower `--min-conf 0.2`; add photos of it in more positions (also half out of frame)\n- **Boxes on hands / things you did not train** -> web page: **+ Background**, capture the empty scene + your hands moving (no boxes), train again; quick fix: `--min-conf 0.5`\n- **The same object gets two boxes** -> `--iou 0.3`\n- **CSI on Jetson fails** -> `gst-launch-1.0 nvarguscamerasrc ! fakesink` must work first; use the system OpenCV (has GStreamer), not pip's\n- **CSI on Pi fails** -> `rpicam-hello` must work first; `sudo apt install -y python3-picamera2`\n- **`onnxruntime is not installed`** -> the venv is not active: `source venv/bin/activate` (Windows: `venv\\Scripts\\activate`), or run the installer again\n- **USB camera will not open** -> `v4l2-ctl --list-devices`, try `--source 1`; close other apps using it\n\n## Use the same model in other tools\n\n- **TESR ROI Studio** - Add a trained model -> `model.onnx`, type = detection\n  (or classification), size = 224, classes from `classes.txt`\n- **Any YOLO decoder** - `output0` has the Ultralytics layout `[1, 4+nc, N]`\n  (cx,cy,w,h in 224-px space + class scores); apply conf filter + NMS\n- **TensorRT / OpenVINO / onnxruntime** - standard ONNX opset 13, static shapes\n",
  "START_HERE.md": "# 🚀 START HERE\n\n```\nเว็บ (เทรน)  →  คอมพิวเตอร์ (ทดสอบ + export)  →  Raspberry Pi / Jetson (ใช้งาน)\n```\n\n## ขั้นที่ 1 — บนคอมพิวเตอร์: ติดตั้ง + ทดสอบ\n```\nWindows : ดับเบิลคลิก install_windows.bat\nLinux   : bash install_linux.sh\n\nvenv\\Scripts\\activate          (Linux: source venv/bin/activate)\npython predict.py              ← เปิดกล้อง เห็นกรอบ + center (x,y) ทุกชิ้นในภาพ · กด q ออก\n```\n\n## ขั้นที่ 2 — บนคอมพิวเตอร์: export ไปอุปกรณ์\n```\npython export.py --target pi                  # Raspberry Pi 5\npython export.py --target jetson              # Jetson Orin Nano / NX / AGX\npython export.py --target jetson_nano         # Jetson Nano (JetPack 4, ทดลอง)\n```\n⚠️ Jetson Nano ด้อยกว่า Jetson Orin Nano มาก — ทั้งความเร็ว และการรองรับซอฟต์แวร์รุ่นใหม่ (ค้างที่ JetPack 4)\n👉 ได้ไฟล์ `exports/tesr-model-pi5.zip` (หรือ `-jetson.zip`) — มีแค่ที่บอร์ดต้องใช้\n\n## ขั้นที่ 3 — บนบอร์ด: ติดตั้ง + รัน\n```\n1. ก๊อป zip ไปที่บอร์ด แล้วแตกไฟล์      (USB stick / scp)\n2. Pi     : bash install_pi.sh\n   Jetson : bash install_jetson.sh\n3. source venv/bin/activate\n4. python predict.py                         # ไม่มีจอ (SSH): python predict.py --headless\n```\nJetson อยากเร็วขึ้น: `bash build_trt.sh` (สร้าง TensorRT บนตัว Jetson เอง · บอกค่า Throughput FP32 vs FP16 ที่วัดได้จริง) แล้ว `python predict.py --trt`\n\n⚠️ Pi: ห้าม `sudo pip3 install` — ใช้ `install_pi.sh` เท่านั้น\n\n---\n\n## ต่อยอด\n\n**ใส่ในโค้ด Python ของคุณเอง** — วาง `predict.py` + `model.onnx` + `config.json` ไว้โฟลเดอร์เดียวกัน:\n```python\nimport cv2\nfrom predict import load_config, Model, decode_multi\n\ncfg = load_config()\nmodel = Model(cfg)                         # โหลดครั้งเดียว นอก loop\nframe = cv2.imread(\"photo.jpg\")            # หรือภาพจากกล้อง\nout = model.run(frame)\nfor d in decode_multi(model, out, 0.3, 0.45):      # ทุกชิ้นในภาพ\n    cx, cy, w, h = d[\"box\"]                          # 0..1 ของภาพ\n    print(d[\"name\"], d[\"conf\"], \"center px:\", int(cx * frame.shape[1]), int(cy * frame.shape[0]))\n```\n👉 เอา `name` / center ไปสั่งแขนกล, PLC, MQTT → Node-RED ได้เลย\n\n**ตีกรอบ ROI / นับของ** — TESR ROI Studio → **+ เพิ่มโมเดลที่เทรนแล้ว** → `model.onnx` · size **224** · คลาสจาก `classes.txt`\n\n**แก้ / เพิ่มคลาส** — หน้าเว็บ → **Load Project** → เลือก zip นี้ (รูป + label อยู่ใน `project/`) → เทรน → ดาวน์โหลดใหม่\n\n**ต้องการแม่นขึ้นอีก / โมเดล YOLO ตัวใหญ่** — หน้าเว็บ → **Download Dataset (YOLO)** → เทรน YOLO\nนั่นคือ **อีกเส้นทางหนึ่ง** คนละชุดคำสั่งกับที่นี่: `train.py` → `run.py` → `export.py`\nของโฟลเดอร์ `yolo-trainer/` ซึ่ง **แปลง** `best.pt` ไม่ใช่ **แพ็ก** `model.onnx`\nและบนอุปกรณ์ต้องลง `ultralytics` เพิ่ม → อ่าน `yolo-trainer/README.md` ก่อน\n\n## ปรับเร็ว ๆ\n\n| อาการ | ลอง |\n|---|---|\n| ไม่มีกรอบเลย (โหมด `multi` ค่าเริ่มต้น — ขึ้น `0 object(s)` / `--headless` พิมพ์ `[]` · ไม่มีคำว่า `none`) | ลด `--min-conf` เช่น `0.2` (ค่าเริ่มต้นคือ `multi_conf` ใน config.json · ยิ่งต่ำยิ่งเจอง่าย) · ถ่ายรูปเพิ่ม |\n| ขึ้น `none` ตลอด (เฉพาะ `--mode single` / `precise` หรือโมเดล classification) | `--min-conf 0.5` (ค่าเริ่มต้น `0.65`) หรือ `--no-proto` |\n| ทักมือ / ของอื่นว่าเป็นวัตถุ | หน้าเว็บ → **+ Background** → ถ่ายฉากว่าง + มือที่ขยับ (ไม่ต้องลากกรอบ) → เทรนใหม่ |\n| กรอบตามช้าไป (แขนกล / สายพานเร็ว) | `--steady normal` หรือ `--steady low` (ค่าเริ่มต้น `high` = นิ่งที่สุด) |\n| เจอวัตถุไม่ครบ | `--min-conf 0.2` · ถ่ายรูปวัตถุนั้นเพิ่มหลายตำแหน่ง |\n| อยากได้แค่ชิ้นหลักชิ้นเดียว | `--mode single` |\n| อยากเก็บคลิปภาพจริง (ไม่มีกรอบ) ไว้ทดสอบ / ทำ ROI | `python predict.py --record clip.mp4` |\n| กล้องไม่เปิด | `--source 1` · ปิดแท็บเว็บ / Zoom ที่ใช้กล้องอยู่ |\n\nรายละเอียดเต็ม → `README_DEPLOY.md`\n\n---\n\n## English\n\n1. **Computer:** `install_windows.bat` (Linux: `bash install_linux.sh`) → `python predict.py`\n2. **Computer:** `python export.py --target pi|jetson|jetson_nano` → `exports/tesr-model-<target>.zip`\n3. **Device:** unzip → `bash install_pi.sh` / `bash install_jetson.sh` → `python predict.py` (Jetson speed-up: `bash build_trt.sh` → `python predict.py --trt`)\n\nNeed more accuracy or a bigger YOLO model? Web page → **Download Dataset (YOLO)**. That is a **different route** with its own `train.py` / `run.py` / `export.py` in `yolo-trainer/` — that `export.py` **converts** `best.pt`, this one **packages** `model.onnx`, and the device needs `ultralytics` too. Read `yolo-trainer/README.md` first.\n",
  "START_HERE_DATASET.md": "# 🚀 START HERE — เทรน YOLO จาก dataset นี้\n\n> ในไฟล์นี้มีรูป + label ที่คุณทำบนเว็บ พร้อมเทรน YOLO (แม่นกว่า, หลายวัตถุจริง)\n> ตรวจโหมดให้อัตโนมัติ: กรอบปกติ / กรอบเอียง (OBB) / classification\n\n## ขั้นที่ 0 — เตรียม (ครั้งเดียว)\n```\n1. โหลดตัวเทรน: github.com/TESR-Channel/AI_vision_Trainer → โฟลเดอร์ yolo-trainer\n2. วางโฟลเดอร์ \"dataset\" นี้ไว้ข้าง train.py\n```\n```\nyolo-trainer/\n├── train.py  run.py  export.py\n└── dataset/   ← โฟลเดอร์นี้\n```\n\n## เลือกว่าจะเทรนที่ไหน 👇\n\n### Ⓐ เทรนบนคอม (แนะนำ — มีการ์ดจอ NVIDIA จะเร็วมาก)\n```\npip install -r requirements.txt\npython train.py            # ได้ best.pt\npython run.py              # ทดสอบกับ webcam\n```\nมีการ์ดจอ NVIDIA → ติดตั้ง PyTorch แบบ CUDA ก่อน (ดู `yolo-trainer/README.md`)\nไม่มีการ์ดจอ → เทรนด้วย CPU ได้ แค่ช้ากว่า\nหน่วยความจำไม่พอ → `python train.py --batch 8 --imgsz 480`\n\n### Ⓑ เทรนบน Jetson Orin Nano เลย (ไม่ต้องมีคอมแรง)\n```\n1. ก๊อป yolo-trainer/ (มี dataset/ อยู่ข้างใน) ไป Jetson\n2. ติดตั้ง ultralytics + PyTorch ตามหัวข้อ Jetson ใน yolo-trainer/README.md\n3. sudo nvpmodel -m 0 && sudo jetson_clocks      # เร่งเต็มสปีด\n4. python3 train.py --batch 8 --imgsz 480         # ได้ best.pt บน Jetson เลย\n5. python3 run.py                                  # รันต่อได้ทันที\n```\n⚠️ ช้ากว่าเทรนบนคอมที่มีการ์ดจอ — เหมาะกับ dataset เล็ก / ไม่มีคอมแรง\n⚠️ Raspberry Pi ไม่เหมาะกับการเทรน — เทรนบนคอมแล้วค่อย export ไป Pi\n\n## เทรนเสร็จ → เอาไปใช้ที่ไหน 👇\n\n| ปลายทาง | ทำอะไร |\n|---|---|\n| 💻 คอมเครื่องเดิม | `python run.py` ใช้ได้เลย |\n| 🍓 Raspberry Pi 5 | บนคอม: `python export.py --target pi` → ก๊อป `best_ncnn_model/` + `run.py` ไป Pi |\n| 🟩 Jetson | ก๊อป `best.pt` + `run.py` ไปรันได้เลย · อยากเร็วขึ้น: บน Jetson `python3 export.py --target jetson` (TensorRT) |\n| 🎯 TESR ROI Studio | `yolo export model=best.pt format=onnx opset=12` → ROI Studio → เพิ่มโมเดล → `best.onnx` |\n| 🧩 โค้ดของคุณเอง | ใช้ `sample_predict.py` + `SAMPLE_README.md` ที่ `export.py` สร้างให้ (มีตัวอย่าง MQTT → Node-RED) |\n\n## เพิ่มคลาสใหม่ทีหลัง\n```\nเว็บ: Load Project → เพิ่มคลาส → ถ่าย + ติด label → Download Dataset (YOLO) ใหม่\nคอม:  python train.py --model best.pt       # ต่อยอดจากโมเดลเดิม\n```\n\n## หมายเหตุ dataset\n- `val/` เป็นรูปจริงเท่านั้น · รูปที่สร้างเพิ่ม (✨) อยู่ใน `train/` → ผลวัดตรงไปตรงมา\n- path ใน dataset ถูกแก้ให้อัตโนมัติโดย train.py ย้ายเครื่องได้\n\n---\n\n## English quick map\n\n| I want to… | Do this |\n|---|---|\n| Set up | put this `dataset/` folder next to `yolo-trainer/train.py` |\n| Train on my PC | `pip install -r requirements.txt` → `python train.py` → `python run.py` |\n| Train on Jetson Orin Nano itself | install ultralytics + PyTorch (yolo-trainer README, Jetson) → `python3 train.py --batch 8 --imgsz 480` |\n| Deploy to Raspberry Pi 5 | on the PC: `python export.py --target pi` → copy `best_ncnn_model/` + `run.py` |\n| Deploy to Jetson | copy `best.pt` + `run.py` · faster: `python3 export.py --target jetson` on the Jetson |\n| Use in ROI Studio | `yolo export model=best.pt format=onnx opset=12` → Add a trained model |\n| Add a class later | web: Load Project → add class → re-download dataset · PC: `python train.py --model best.pt` |\n",
  "install_windows.bat": "@echo off\nREM ==== TESR web model - one-click installer (Windows) ====\nsetlocal\nset \"PY=python\"\npy -3 -c \"print()\" >nul 2>nul && set \"PY=py -3\"\necho Using: %PY%\n%PY% -m venv venv || goto err\ncall venv\\Scripts\\activate.bat\npython -m pip install --upgrade pip\npip install -r requirements.txt || goto err\necho.\necho ============================================\necho  Done! To run your model:\necho    venv\\Scripts\\activate\necho    python predict.py\necho ============================================\npause\nexit /b 0\n:err\necho.\necho Install failed - see README_DEPLOY.md (needs Python 3.8 or newer from python.org).\npause\nexit /b 1\n",
  "install_linux.sh": "#!/usr/bin/env bash\n# ==== TESR web model - installer for a Linux / macOS PC ====\n# Raspberry Pi -> install_pi.sh    Jetson -> install_jetson.sh\nset -e\ncd \"$(dirname \"$0\")\"\npython3 -m venv venv\n. venv/bin/activate\npython -m pip install --upgrade pip\npip install -r requirements.txt\necho\necho \"Done! Run:  source venv/bin/activate && python predict.py\"\n",
  "install_pi.sh": "#!/usr/bin/env bash\n# ==== TESR web model - installer for Raspberry Pi 5 (Raspberry Pi OS 64-bit) ====\n# OpenCV, NumPy and Picamera2 come from apt (Picamera2 cannot be pip-installed);\n# the venv sees them through --system-site-packages, pip adds only onnxruntime.\n# Never \"sudo pip3 install\" - Pi OS blocks it (PEP 668) and it can break the system.\nset -e\ncd \"$(dirname \"$0\")\"\nif [ \"$(uname -m)\" != \"aarch64\" ]; then\n  echo \"WARNING: this is not a 64-bit OS ($(uname -m)). onnxruntime needs 64-bit Raspberry Pi OS.\"\nfi\nsudo apt update\nsudo apt install -y python3-venv python3-opencv python3-numpy python3-picamera2\npython3 -m venv --system-site-packages venv\n. venv/bin/activate\npip install --upgrade pip\npip install onnxruntime\npython -c \"import onnxruntime, cv2, numpy; print('onnxruntime', onnxruntime.__version__, '| OpenCV', cv2.__version__)\"\necho\necho \"Done! Run:\"\necho \"  source venv/bin/activate\"\necho \"  python predict.py                 # camera type from config.json\"\necho \"  python predict.py --camera csi    # ribbon camera\"\necho \"  python predict.py --camera usb    # USB webcam\"\n",
  "install_jetson.sh": "#!/usr/bin/env bash\n# ==== TESR web model - installer for NVIDIA Jetson (Orin Nano / Orin NX / AGX Orin) ====\n# Uses the system OpenCV (it has GStreamer, which the CSI camera needs; pip's\n# opencv-python does not) through a venv with --system-site-packages.\nset -e\ncd \"$(dirname \"$0\")\"\n[ -f /etc/nv_tegra_release ] && echo \"L4T: $(head -n1 /etc/nv_tegra_release)\"\nsudo apt update\nsudo apt install -y python3-venv python3-pip python3-numpy\npython3 -c \"import cv2\" 2>/dev/null || sudo apt install -y python3-opencv\npython3 -m venv --system-site-packages venv\n. venv/bin/activate\npip install --upgrade pip\n# CPU onnxruntime works everywhere. For the GPU (course chapter 6):\n#   bash build_trt.sh  then  python predict.py --trt\n#   --trt runs model_fp16.engine through JetPack's TensorRT Python module\n#   (python3-libnvinfer, seen through --system-site-packages); if it cannot,\n#   predict.py says why and runs on onnxruntime instead.\npip install onnxruntime || {\n  echo \"pip could not install onnxruntime for this Python ($(python3 -V)).\"\n  echo \"Install the Jetson build of onnxruntime for your JetPack, then re-run.\"\n  exit 1; }\npython -c \"import onnxruntime as o, cv2; print('onnxruntime', o.__version__, o.get_available_providers()); import re; print('OpenCV GStreamer:', bool(re.search(r'GStreamer:\\\\s+YES', cv2.getBuildInformation())))\"\npython -c \"import tensorrt as t; print('TensorRT (for --trt):', t.__version__)\" 2>/dev/null \\\n  || echo \"TensorRT Python module not found - only --trt needs it:  sudo apt install -y python3-libnvinfer\"\necho\necho \"Done! Run:\"\necho \"  source venv/bin/activate\"\necho \"  python predict.py --camera csi    # ribbon camera (nvarguscamerasrc)\"\necho \"  python predict.py --camera usb    # USB webcam\"\necho \"Optional GPU speed-up:  bash build_trt.sh   then   python predict.py --trt\"\n",
  "build_trt.sh": "#!/usr/bin/env bash\n# ==== ONNX -> TensorRT engine on the Jetson (run ON the Jetson) ====\n# trtexec ships with JetPack. The engine is tied to THIS device + TensorRT\n# version, so always build it on the board that will run it.\nset -e\ncd \"$(dirname \"$0\")\"\nTRTEXEC=/usr/src/tensorrt/bin/trtexec\n[ -x \"$TRTEXEC\" ] || TRTEXEC=$(command -v trtexec || true)\nif [ -z \"$TRTEXEC\" ]; then\n  echo \"trtexec not found - install TensorRT:  sudo apt install -y tensorrt\"; exit 1\nfi\necho \"== FP32 baseline ==\"\n$TRTEXEC --onnx=model.onnx --saveEngine=model_fp32.engine 2>&1 | grep -E \"Throughput|mean =|PASSED|FAILED|ERROR\" || true\necho \"== FP16 (recommended on Jetson) ==\"\n$TRTEXEC --onnx=model.onnx --saveEngine=model_fp16.engine --fp16 2>&1 | grep -E \"Throughput|mean =|PASSED|FAILED|ERROR\" || true\nls -lh model_*.engine 2>/dev/null || true\necho\necho \"Compare the two 'Throughput' lines above - those are YOUR measured numbers.\"\necho \"Run it:  python predict.py --trt   (loads model_fp16.engine; needs the JetPack TensorRT\"\necho \"        Python module: sudo apt install -y python3-libnvinfer)\"\n",
};
